drop function if exists public.business_qr_analytics(uuid);
create or replace function public.business_qr_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_out jsonb; begin if auth.uid() is null then raise exception 'authentication required'; end if; if not exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager','analyst')) and not exists(select 1 from profiles p where p.id=auth.uid() and p.is_admin) then raise exception 'not authorized'; end if; select jsonb_build_object('business_id',p_business_id,'qr_scans',coalesce(sum(x.qr_scans),0),'check_ins',coalesce(sum(x.check_ins),0),'unique_users',coalesce(sum(x.unique_users),0),'locations',count(l.id),'locations_with_scans',count(*) filter(where coalesce(x.qr_scans,0)>0),'by_location',coalesce(jsonb_agg(jsonb_build_object('location_id',l.id,'location_name',l.name,'qr_scans',coalesce(x.qr_scans,0),'check_ins',coalesce(x.check_ins,0),'unique_users',coalesce(x.unique_users,0),'last_scan_at',x.last_scan_at) order by l.name),'[]'::jsonb)) into v_out from locations l left join lateral(select count(*) filter(where ci.verification_method='qr') qr_scans,count(*) check_ins,count(distinct ci.user_id) unique_users,max(ci.checked_in_at) last_scan_at from check_ins ci where ci.location_id=l.id and ci.checked_in_at between p_start and p_end)x on true where l.business_id=p_business_id and l.is_active=true; return v_out; end $$;
grant execute on function public.business_qr_analytics(uuid,timestamptz,timestamptz) to authenticated;
